/* OPAL Chart compatibility layer for the dashboard's line/bar charts.
 * This is not the upstream Chart.js distribution. It intentionally implements
 * only the subset used by OPAL templates so production does not depend on a CDN.
 */
(function(global){'use strict';
function number(v){v=Number(v);return Number.isFinite(v)?v:0}
function color(value,fallback){return typeof value==='string'&&value?value:fallback}
function pick(value,index,fallback){return Array.isArray(value)?color(value[index%value.length],fallback):color(value,fallback)}
function size(canvas){var rect=canvas.getBoundingClientRect(),ratio=Math.max(1,global.devicePixelRatio||1),w=Math.max(280,Math.round(rect.width||canvas.parentElement&&canvas.parentElement.clientWidth||600)),h=Math.max(220,Math.round(rect.height||canvas.parentElement&&canvas.parentElement.clientHeight||320));canvas.width=w*ratio;canvas.height=h*ratio;canvas.style.width=w+'px';canvas.style.height=h+'px';var ctx=canvas.getContext('2d');ctx.setTransform(ratio,0,0,ratio,0,0);return{ctx:ctx,w:w,h:h}}
function limits(config,values){var scales=config.options&&config.options.scales||{},horizontal=config.options&&config.options.indexAxis==='y',axis=horizontal?scales.x||{}:scales.y||{},min=axis.min!=null?number(axis.min):Math.min(0,Math.min.apply(null,values)),max=axis.max!=null?number(axis.max):Math.max.apply(null,values.concat([1]));if(max<=min)max=min+1;return{min:min,max:max}}
function label(ctx,text,x,y,align){ctx.fillStyle='#655d70';ctx.font='12px Arial,sans-serif';ctx.textAlign=align||'center';ctx.textBaseline='middle';ctx.fillText(String(text),x,y)}
function grid(ctx,left,top,right,bottom,steps){ctx.strokeStyle='rgba(100,90,120,.14)';ctx.lineWidth=1;for(var i=0;i<=steps;i++){var y=top+(bottom-top)*i/steps;ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke()}}
function legend(ctx,datasets,w){var x=18,y=14;ctx.font='12px Arial,sans-serif';ctx.textAlign='left';ctx.textBaseline='middle';datasets.forEach(function(ds,i){ctx.fillStyle=pick(ds.backgroundColor,i,'#7254d8');ctx.fillRect(x,y-5,10,10);ctx.fillStyle='#574f63';ctx.fillText(ds.label||'',x+15,y);x+=Math.min(180,ctx.measureText(ds.label||'').width+45);if(x>w-120){x=18;y+=18}});return y+12}
function renderBar(chart,box){var c=chart.config,ctx=box.ctx,w=box.w,h=box.h,labels=(c.data&&c.data.labels)||[],sets=(c.data&&c.data.datasets)||[],horizontal=c.options&&c.options.indexAxis==='y',all=[];sets.forEach(function(ds){(ds.data||[]).forEach(function(v){all.push(number(v))})});var lim=limits(c,all),top=legend(ctx,sets,w)+18,left=horizontal?110:52,right=w-18,bottom=h-46;grid(ctx,left,top,right,bottom,5);if(horizontal){var group=(bottom-top)/Math.max(1,labels.length),bar=Math.max(4,group*.72/Math.max(1,sets.length));labels.forEach(function(l,i){label(ctx,l,left-8,top+group*(i+.5),'right');sets.forEach(function(ds,j){var v=number((ds.data||[])[i]),x=left+(right-left)*(v-lim.min)/(lim.max-lim.min),y=top+group*i+group*.14+j*bar;ctx.fillStyle=pick(ds.backgroundColor,i,'rgba(114,84,216,.75)');ctx.fillRect(left,y,Math.max(0,x-left),bar*.82)})})}else{var groupW=(right-left)/Math.max(1,labels.length),barW=Math.max(3,groupW*.72/Math.max(1,sets.length));labels.forEach(function(l,i){label(ctx,l,left+groupW*(i+.5),bottom+20);sets.forEach(function(ds,j){var v=number((ds.data||[])[i]),zero=bottom-(bottom-top)*(0-lim.min)/(lim.max-lim.min),y=bottom-(bottom-top)*(v-lim.min)/(lim.max-lim.min),x=left+groupW*i+groupW*.14+j*barW;ctx.fillStyle=pick(ds.backgroundColor,i,'rgba(114,84,216,.75)');ctx.fillRect(x,Math.min(y,zero),barW*.82,Math.abs(zero-y))})});for(var k=0;k<=5;k++){var val=lim.max-(lim.max-lim.min)*k/5;label(ctx,Math.round(val*100)/100,left-8,top+(bottom-top)*k/5,'right')}}}
function renderLine(chart,box){var c=chart.config,ctx=box.ctx,w=box.w,h=box.h,labels=(c.data&&c.data.labels)||[],sets=(c.data&&c.data.datasets)||[],all=[];sets.forEach(function(ds){(ds.data||[]).forEach(function(v){if(v!=null)all.push(number(v))})});var lim=limits(c,all),top=legend(ctx,sets,w)+18,left=52,right=w-18,bottom=h-46;grid(ctx,left,top,right,bottom,5);labels.forEach(function(l,i){label(ctx,l,left+(right-left)*i/Math.max(1,labels.length-1),bottom+20)});for(var k=0;k<=5;k++){var val=lim.max-(lim.max-lim.min)*k/5;label(ctx,Math.round(val*100)/100,left-8,top+(bottom-top)*k/5,'right')}sets.forEach(function(ds,j){ctx.strokeStyle=pick(ds.borderColor,j,'#7254d8');ctx.fillStyle=pick(ds.backgroundColor,j,'rgba(114,84,216,.15)');ctx.lineWidth=2;ctx.beginPath();var started=false,points=[];(ds.data||[]).forEach(function(raw,i){if(raw==null)return;var v=number(raw),x=left+(right-left)*i/Math.max(1,labels.length-1),y=bottom-(bottom-top)*(v-lim.min)/(lim.max-lim.min);points.push([x,y]);if(!started){ctx.moveTo(x,y);started=true}else ctx.lineTo(x,y)});ctx.stroke();points.forEach(function(p){ctx.beginPath();ctx.arc(p[0],p[1],3,0,Math.PI*2);ctx.fill()})})}
function Chart(canvas,config){if(!(this instanceof Chart))return new Chart(canvas,config);this.canvas=typeof canvas==='string'?document.getElementById(canvas):canvas;this.config=config||{};this._listener=this.resize.bind(this);if(this.canvas){this.resize();global.addEventListener('resize',this._listener)}}
Chart.prototype.resize=function(){if(!this.canvas)return;var box=size(this.canvas);box.ctx.clearRect(0,0,box.w,box.h);if((this.config.type||'bar')==='line')renderLine(this,box);else renderBar(this,box)};
Chart.prototype.update=Chart.prototype.resize;Chart.prototype.destroy=function(){global.removeEventListener('resize',this._listener);if(this.canvas){var b=size(this.canvas);b.ctx.clearRect(0,0,b.w,b.h)}};Chart.register=function(){};Chart.defaults={};global.Chart=Chart;
})(window);
